// Generated by scripts/redesign-capture-bars.mjs from the running app. Do not edit.
window.REAL_BARS = {"library":"<div id=\"lib-top\" class=\"lib-fullview-only lib-top-overflow1\">\n      <div class=\"lib-logo-gap\" data-was-hidden=\"\"></div>\n      <div id=\"lib-top-left\">\n      <div>\n        <button class=\"lib-btn lib-pill\" id=\"lib-sort-btn\" title=\"Sort by\"><svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M7 15V3M4 6l3-3 3 3\"></path><path d=\"M13 11h7M13 16h4M13 6h9\"></path></svg><span class=\"lbl\" id=\"lib-sort-label\">Date taken</span></button>\n        <div class=\"lib-menu\" id=\"lib-sort-menu\" data-was-hidden=\"\">\n          <div class=\"grp-label\">Sort by</div>\n          <select id=\"lib-sort\" data-was-hidden=\"\">\n            <option value=\"name\">Name</option>\n            <option value=\"mtime\">Date modified</option>\n            <option value=\"date\">Date taken</option>\n            <option value=\"iso\">ISO</option>\n            <option value=\"shutter\">Shutter speed</option>\n            <option value=\"aperture\">Aperture</option>\n            <option value=\"focal\">Focal length</option>\n            <option value=\"camera\">Camera</option>\n            <option value=\"edited\">Edit status</option>\n            \n            <option value=\"editedts\">Date edited</option>\n          </select>\n          <!-- #13: matches the wireframe's own 3 keys (Library View.html:238-241) exactly —\n               Name/Rating/Camera stay reachable via the list-view's own column headers\n               (data-sort on .lib-lh-cell), a separate real feature the wireframe's mock has no\n               equivalent surface for, so removing them from just this menu keeps the feature\n               without keeping the menu's own divergence from the wireframe. \"Date added\" reuses\n               the existing 'mtime' sort key (file mtime) — the closest available proxy; there is\n               no distinct added-to-catalog timestamp anywhere in this app. -->\n          <div class=\"opt sel\" data-sortval=\"date\"><span>Date taken</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6 9 17l-5-5\"></path></svg></div><div class=\"opt\" data-sortval=\"mtime\"><span>Date added</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div><div class=\"opt\" data-sortval=\"editedts\"><span>Date edited</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div>\n          <hr>\n          <!-- Newest first / Oldest first radio pair, replacing the old single \"Reverse order\"\n               toggle — Library View.html:244-245, copied literally. -->\n          <div class=\"opt\" data-sortdir=\"desc\"><span>Newest first</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div>\n          <div class=\"opt sel\" data-sortdir=\"asc\"><span>Oldest first</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6 9 17l-5-5\"></path></svg></div>\n        </div>\n      </div>\n      <div id=\"lib-filters-btn-wrap\">\n        <button class=\"lib-btn lib-pill\" id=\"lib-filters-btn\" title=\"Subfolders, type/camera/lens/ISO/duplicates/sync/rating/tag filters\"><svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"4\" y1=\"6\" x2=\"20\" y2=\"6\"></line><line x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\"></line><line x1=\"4\" y1=\"18\" x2=\"20\" y2=\"18\"></line><circle cx=\"9\" cy=\"6\" r=\"2\" fill=\"var(--bg)\"></circle><circle cx=\"15\" cy=\"12\" r=\"2\" fill=\"var(--bg)\"></circle><circle cx=\"9\" cy=\"18\" r=\"2\" fill=\"var(--bg)\"></circle></svg><span class=\"lbl\">Filters</span><span id=\"lib-filters-badge\" data-was-hidden=\"\"></span></button>\n      </div>\n      <!-- Grid/List only, matching Library View.html's 2-button toggle — Compare moved into the\n           gear's View menu (below) per explicit decision: it's a real feature but not common\n           enough to earn a permanent topbar slot next to the two everyday view modes. -->\n      <div class=\"lib-seg lib-viewtoggle\" id=\"lib-viewmode-seg\">\n        <button data-v=\"grid\" title=\"Grid view\" class=\"on\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"></rect><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"></rect><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"></rect><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"></rect></svg></button>\n        <button data-v=\"list\" title=\"List view\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 6h18M3 12h18M3 18h18\"></path></svg></button>\n      </div>\n      </div>\n      <div class=\"lib-spacer\" data-was-hidden=\"\"></div>\n      <!-- Single search feature, one icon: plain filename/keyword search and AI/CLIP semantic\n           search (e.g. \"a dog on a beach\") both live in this one box — typing filters live\n           (plain match), and Enter with non-empty text ALWAYS also runs the AI/CLIP semantic\n           search (runClipTextSearch, wired below), not only when the plain match is empty.\n           HANDOVER §3.11 — this comment previously claimed the empty-match condition. Per\n           explicit decision, there is no separate AI-search button/icon: two search icons read\n           as two features when there's really only one. Under deskx this sits centred in\n           #lib-top-center, same slot as the Editor's filename/status title. -->\n      <div id=\"lib-top-center\">\n      <div class=\"lib-search-wrap\">\n        <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"></circle><path d=\"M20 20l-3.6-3.6\"></path></svg>\n        <input id=\"lib-search\" placeholder=\"Search\" title=\"Search by filename, or press Enter to describe a photo (e.g. &quot;dog on a beach&quot;) for AI search\">\n      </div>\n      </div>\n      <div id=\"lib-top-right\">\n      <!-- 2026-09-11 (topbar parity pass): zoom + flags merged into ONE cluster\n           (#lib-zoomflag-cluster), mirroring the Editor's own #fx-zoom-ctrl (chromasmith-22.html)\n           which holds its zoom slider AND flag buttons as one group carrying a single divider.\n           Previously these were two independent flex children of #lib-top-right, each getting\n           the row's own 8px gap on both sides — that read as \"zoom  flags\" evenly spaced same as\n           \"flags  All FX\", when the Editor treats zoom+flags as one visual unit and only dividers\n           its OUTER edges. See body.deskx #lib-overlay #lib-zoomflag-cluster below for the exact\n           divider/gap values, copied literally from #fx-deskbar-tools .fx-zoom-ctrl /\n           body.deskx .fx-zoom-ctrl. -->\n      <div id=\"lib-zoomflag-cluster\">\n      <div class=\"lib-zoomrow\">\n        <button type=\"button\" class=\"lib-zoom-btn\" id=\"lib-zoom-out\" title=\"Smaller thumbnails\" data-conditional=\"\"><svg viewBox=\"0 0 24 24\" width=\"12\" height=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg></button>\n        <input type=\"range\" id=\"lib-thumbsize\" min=\"90\" max=\"320\" step=\"10\" title=\"Thumbnail size\">\n        <button type=\"button\" class=\"lib-zoom-btn\" id=\"lib-zoom-in\" title=\"Larger thumbnails\" data-conditional=\"\"><svg viewBox=\"0 0 24 24\" width=\"12\" height=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"></line><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg></button>\n      </div>\n      <!-- Flag row: applies to the selected Library photos. The Editor's separate toolbar\n           continues to rate only the photo being edited via window.chromasmithToggle*().\n           Reject icon is 'flagRed' (not the generic 'close' this used to render) — the Editor's\n           own reject button (#btn-flag-red, chromasmith-22.html) uses 'flagRed' specifically so\n           the two bars show the literal same glyph, not two different X shapes at two different\n           stroke weights. -->\n      <div class=\"lib-flagrow\" id=\"lib-flagrow\" data-conditional=\"\">\n        <button class=\"lib-btn lib-btn-icon flag-btn\" id=\"lib-flag-reject\" title=\"Reject selected photos\" disabled=\"\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6L6 18\" stroke=\"currentColor\" stroke-width=\"2.4\" fill=\"none\"></path></svg></button>\n        <button class=\"lib-btn lib-btn-icon flag-btn\" id=\"lib-flag-pick\" title=\"Pick selected photos\" disabled=\"\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 21V4\" fill=\"none\"></path><path d=\"M5 4h13l-3.2 4.5L18 13H5z\" fill=\"currentColor\" stroke=\"none\"></path></svg></button>\n        <button class=\"lib-btn lib-btn-icon flag-btn\" id=\"lib-flag-fav\" title=\"Favorite selected photos\" disabled=\"\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 20.5s-7.5-4.6-10-9.1C.6 8.1 2 4.8 5.2 4c2-.5 4 .3 5.3 2 1.3-1.7 3.3-2.5 5.3-2 3.2.8 4.6 4.1 3.2 7.4-2.5 4.5-10 9.1-10 9.1z\" fill=\"currentColor\" stroke=\"none\"></path></svg></button>\n      </div>\n      </div>\n      <button class=\"lib-btn lib-pill\" id=\"lib-allfx-btn\" title=\"Apply a look to every selected photo\" disabled=\"\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 3v4M3 5h4\"></path><path d=\"M13 3l2.4 6.6L22 12l-6.6 2.4L13 21l-2.4-6.6L4 12l6.6-2.4z\"></path></svg><span class=\"lbl\">All FX</span></button>\n      <button class=\"lib-btn lib-btn-export\" id=\"lib-export-btn\" title=\"Export selected photos — ⌘E\" disabled=\"\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v12M8 11l4 4 4-4\"></path><path d=\"M5 21h14\"></path></svg><span class=\"lbl\">Export</span></button>\n      <!-- id (not just a bare positioning div) so body.deskx can give it the SAME margin-left/\n           padding-left/border-left divider as the Editor's own #fx-settings, instead of just the\n           row's flat 8px gap — see the #lib-settings CSS rule below, copied from #fx-settings. -->\n      <div id=\"lib-settings\">\n        <button class=\"lib-btn lib-btn-icon\" id=\"lib-view-menu-btn\" title=\"View settings\"><svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"></circle><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.6 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.6a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"></path></svg></button>\n        <!-- CHR-147 fix: reverted to a flat single-list menu. The 2026-09-11 two-column\n             category drill-down (matching the Editor's #fx-settings-menu) hid every option\n             outside the default \"Library\" pane behind a tab click with no strong visual cue,\n             so toggles like \"Hide flag & type icons\" and the theme switch appeared unresponsive\n             — reported as \"settings button doesn't work in library view\". Library has far fewer\n             settings than the Editor, so the drill-down's scroll-avoidance tradeoff wasn't\n             worth the discoverability cost here. -->\n        <div class=\"lib-menu\" id=\"lib-view-menu\" data-was-hidden=\"\">\n          <div class=\"grp-label\">Library</div>\n          <button class=\"lib-btn opt-action\" id=\"lib-pick\" title=\"Choose root folder\"><svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 7a2 2 0 0 1 2-2h3.9a2 2 0 0 1 1.6.8l.9 1.2H19a2 2 0 0 1 2 2v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"></path></svg><span>Choose folder…</span></button>\n          <button class=\"lib-btn opt-action\" id=\"lib-gphotos\" title=\"Import from Google Photos\"><svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M17.5 19a4.5 4.5 0 0 0 .5-8.97A6 6 0 0 0 6.1 11.2 3.9 3.9 0 0 0 6.5 19z\"></path></svg><span>Import from Google Photos…</span></button>\n          <button class=\"lib-btn opt-action\" id=\"lib-recent\" title=\"Recent folders &amp; the Google Photos Download cache\"><svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 7v5l3.5 2\"></path></svg><span>Recent folders…</span></button>\n          <button class=\"lib-btn opt-action\" id=\"lib-info-btn\" title=\"Get Info for the selected photo — I\"><svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 11v5M12 8h.01\"></path></svg><span>Get Info</span></button>\n          <button class=\"lib-btn opt-action\" id=\"lib-expand\" title=\"Full-window view — G\"><svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 8V5a2 2 0 0 1 2-2h3M16 3h3a2 2 0 0 1 2 2v3M21 16v3a2 2 0 0 1-2 2h-3M8 21H5a2 2 0 0 1-2-2v-3\"></path></svg><span>Full-window view</span></button>\n          <button class=\"lib-btn opt-action\" id=\"lib-compare-btn\" title=\"Compare two photos/looks side by side — C\"><svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 3a9 9 0 0 1 0 18z\" fill=\"currentColor\" stroke=\"none\" opacity=\".55\"></path></svg><span>Compare view</span></button>\n          <hr>\n          <div class=\"grp-label\">Thumbnails</div>\n          <div class=\"opt\" id=\"lib-hideicons\"><span>Hide flag &amp; type icons</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div>\n          <div class=\"opt\" id=\"lib-zerogap\"><span>No spacing between photos</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div>\n          <div class=\"opt\" id=\"lib-showtitle\"><span>Show title</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div>\n          <button class=\"lib-btn opt-action opt-toggle\" id=\"lib-aspect-toggle\" title=\"Show thumbnails at their real aspect ratio instead of cropped to a square. Only available for folders under 400 photos (larger folders use a virtualized grid this can't apply to).\"><span>Real aspect ratio</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></button>\n          <hr>\n          <div class=\"grp-label\">Metadata overlay</div>\n          <select id=\"lib-metadisp\" data-was-hidden=\"\">\n            <option value=\"off\">Off</option>\n            <option value=\"hover\">On hover</option>\n            <option value=\"always\">Always on</option>\n          </select>\n          <div class=\"opt sel\" data-metaval=\"off\"><span>Off</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6 9 17l-5-5\"></path></svg></div>\n          <div class=\"opt\" data-metaval=\"always\"><span>Always on</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div>\n          <div class=\"opt\" data-metaval=\"hover\"><span>On hover</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div>\n          <hr>\n          <div class=\"grp-label\">Panels</div>\n          <button class=\"lib-btn opt-action opt-toggle on\" id=\"lib-tree-toggle\" title=\"Show/hide the sidebar (collections, cloud sources, folder tree)\"><span>Show sidebar</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6 9 17l-5-5\"></path></svg></button>\n          <hr>\n          <div class=\"grp-label\">Appearance</div>\n          <div class=\"opt sel\" data-theme=\"dark\"><span>Dark</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6 9 17l-5-5\"></path></svg></div>\n          <div class=\"opt\" data-theme=\"light\"><span>Light</span><svg class=\"check\" viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" data-was-hidden=\"\"><path d=\"M20 6 9 17l-5-5\" data-was-hidden=\"\"></path></svg></div>\n        </div>\n      </div>\n      </div>\n    </div>","editor":"<div id=\"fx-deskbar\">\n    <!-- 2026-09-10 (3.1.9/3.1.10): #fx-deskbar-left/-right exist so body.deskx can lay the bar\n         out as a real 3-column grid (1fr auto 1fr — Editor (Developer) View.dc.html's own\n         .topbar) instead of one flex row with the title absolutely centred on top of it. The\n         centred title only ever LOOKED right by coincidence, whenever the two side clusters\n         happened to weigh about the same — shrinking the left cluster and moving Export/All FX\n         (this file's own history: 045993e removed 6 always-visible buttons, 6627253 removed 4\n         more) made the actual overlap LESS likely, but never addressed the root cause, and\n         editor_responsive_qa.mjs's OVERLAP check still failed it at plain 1440×900 with nothing\n         narrow or unusual about the window. Grid columns can't overlap by construction, so this\n         fixes the class of bug, not just today's specific collision. -->\n    <div id=\"fx-deskbar-left\">\n      <button class=\"fx-db fx-db-icon\" id=\"db-lib-btn\" title=\"Photo library (L)\" data-conditional=\"\"><span class=\"fx-db-ic\" id=\"db-lib-ic\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 7a2 2 0 0 1 2-2h3.9a2 2 0 0 1 1.6.8l.9 1.2H19a2 2 0 0 1 2 2v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"></path></svg></span></button>\n      <!-- 3.1.1: undo/redo used to be two bare .fx-db buttons, reading as unaligned with the rest\n           of the bar's filled-tile buttons — wrapped in a bordered pill matching the wireframe's\n           own .undogrp (Editor (Developer) View.dc.html:41-43): one outer border, square inner\n           corners, a hairline divider between the two. -->\n      <div class=\"fx-undogrp\">\n        <button class=\"fx-db fx-db-icon\" id=\"btn-undo-db\" title=\"Undo (⌘Z) · hold for edit history · shift-click to reset\" disabled=\"\"><span class=\"fx-db-ic\" id=\"db-undo\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"9 14 4 9 9 4\"></polyline><path d=\"M20 20v-7a4 4 0 0 0-4-4H4\"></path></svg></span></button>\n        <button class=\"fx-db fx-db-icon\" id=\"btn-redo-db\" title=\"Redo (⌘Y)\" disabled=\"\"><span class=\"fx-db-ic\" id=\"db-redo\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"15 14 20 9 15 4\"></polyline><path d=\"M4 20v-7a4 4 0 0 1 4-4h12\"></path></svg></span></button>\n      </div>\n      <div id=\"db-history-wrap\" data-conditional=\"\">\n        <button class=\"fx-db fx-db-icon\" id=\"btn-export-history\" title=\"Edit &amp; export history for this photo\"><span class=\"fx-db-ic\" id=\"db-history\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 7v5l3.5 2\"></path></svg></span></button>\n      </div>\n    <button class=\"db-btn\" id=\"btn-before\" title=\"Press and hold to see the original\" disabled=\"\"><span class=\"fx-db-ic\" id=\"ic-before\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7Z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg></span></button><button id=\"btn-fx-fullres\" class=\"zc-ic db-btn\" title=\"Full resolution — renders the whole preview at full source resolution instead of the usual capped size. Costs more GPU time; drops to the capped size automatically while dragging a slider\"><span class=\"fx-db-ic\" id=\"ic-fullres\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"14\" rx=\"1\"></rect><path d=\"M8 21h8M12 18v3\"></path></svg></span></button></div>\n    <!-- \"Reset all edits\" moved into the ⋯ overflow menu (ovfBuild()) — the one genuinely rare,\n         semi-destructive action in the always-visible cluster; Undo/Redo already cover the\n         common \"I changed my mind\" case. -->\n    <div id=\"fx-deskbar-title\"><span id=\"db-title-name\">portrait</span><span id=\"db-title-status\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\" class=\"\">512 × 384 · PNG</span></div>\n    <div id=\"fx-deskbar-right\">\n      <div id=\"fx-deskbar-tools\"><div class=\"btn-row fx-mini-row\" id=\"fx-preview-tools\">\n          <button class=\"db-btn\" id=\"btn-editor-bg\" title=\"Editor background colour (also right-click the empty area around the photo)\" data-conditional=\"\"><span></span></button>\n          \n          <button class=\"db-btn\" id=\"btn-split\" title=\"Split before/after view\" data-conditional=\"\"><span class=\"fx-db-ic\" id=\"ic-split\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"></rect><path d=\"M12 4v16\"></path><path d=\"M8 10l-2 2 2 2M16 10l2 2-2 2\"></path></svg></span></button>\n          <div>\n            <button class=\"db-btn db-btn-narrow\" id=\"btn-split-menu\" title=\"Choose what the split's before-side compares against\" data-was-hidden=\"\"><span class=\"fx-db-ic\" id=\"ic-splitmenu\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M6 9l6 6 6-6\"></path></svg></span></button>\n            <div id=\"fx-split-popover\" data-was-hidden=\"\"></div>\n          </div>\n          <div>\n            <button class=\"db-btn\" id=\"btn-history\" title=\"Edit history timeline\" data-conditional=\"\"><span class=\"fx-db-ic\" id=\"ic-timeline\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 7v5l3.5 2\"></path></svg></span></button>\n            <div id=\"fx-timeline-popover\" data-was-hidden=\"\"></div>\n          </div>\n          <button class=\"db-btn\" id=\"btn-hist\" title=\"Toggle scope overlay\" data-conditional=\"\"><span class=\"fx-db-ic\" id=\"ic-scope\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 20V9M8 20V4M13 20v-8M18 20V7\"></path></svg></span></button>\n          <!-- Gamut warning's own toggle button lived here (3.1.6: \"gamut button should be\n               removed but can be enabled from the View menu bar\") — removed; toggleGamutWarn()\n               is now reached from the View menu only (viewMenuBuild()) and safely no-ops the\n               button-highlight step when #btn-gamut-warn doesn't exist. -->\n          <select id=\"sel-scope-mode\" title=\"Scope type\" data-was-hidden=\"\">\n            <option value=\"hist\">Histogram</option><option value=\"wave\">Waveform</option>\n            <option value=\"parade\">RGB Parade</option><option value=\"vector\">Vectorscope</option>\n          </select>\n        </div><div class=\"fx-zoom-ctrl\" id=\"fx-zoom-ctrl\">\n          <button class=\"zc-ic\" id=\"btn-zoom-out\" title=\"Zoom out\"><span class=\"fx-db-ic\" id=\"ic-zoom-out\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg></span></button>\n          <input type=\"range\" class=\"fx-slider\" id=\"fx-zoom-slider\" min=\"25\" max=\"800\" value=\"100\" step=\"1\" title=\"Drag to zoom · double-click to fit the whole image\">\n          <button class=\"zc-ic\" id=\"btn-zoom-in\" title=\"Zoom in\"><span class=\"fx-db-ic\" id=\"ic-zoom-in\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"></line><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg></span></button>\n          <span id=\"fx-zoom-pct\" title=\"Scroll to zoom · drag to pan · double-click to fit\">100%</span>\n          <button id=\"btn-loupe\" title=\"True 1:1 view — renders a native-resolution crop through the full pipeline so grain &amp; halation appear at real export scale\" data-conditional=\"\">1:1</button>\n          <!-- 2026-09-10: \"zc-ic\" alone has no background/border/color of its own — relies\n               entirely on the parent \".fx-zoom-ctrl button\" rule for its actual look, which\n               isn't there once relocatePreviewTools() parks this in the left cluster under\n               deskx. Added \"db-btn\" alongside it for that reset (matches its new neighbour, Show\n               original); zc-ic's own 28px sizing still wins by source order so web/mobile mode\n               (where it stays inside .fx-zoom-ctrl, sized like its zoom-cluster siblings) is\n               visually unchanged. -->\n          \n          <button id=\"btn-flag-red\" class=\"flag-btn flag-btn-red\" title=\"Reject (Library)\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6L6 18\" stroke=\"currentColor\" stroke-width=\"2.4\" fill=\"none\"></path></svg></button>\n          <button id=\"btn-flag-green\" class=\"flag-btn flag-btn-green\" title=\"Green flag (Library)\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 21V4\" fill=\"none\"></path><path d=\"M5 4h13l-3.2 4.5L18 13H5z\" fill=\"currentColor\" stroke=\"none\"></path></svg></button>\n          <button id=\"btn-favorite\" class=\"flag-btn flag-btn-fav\" title=\"Favorite (Library)\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 20.5s-7.5-4.6-10-9.1C.6 8.1 2 4.8 5.2 4c2-.5 4 .3 5.3 2 1.3-1.7 3.3-2.5 5.3-2 3.2.8 4.6 4.1 3.2 7.4-2.5 4.5-10 9.1-10 9.1z\" fill=\"currentColor\" stroke=\"none\"></path></svg></button>\n        </div></div>\n      <button class=\"fx-db js-allfx\" title=\"Toggle grain, halation, bloom &amp; borders all at once\"><span class=\"fx-db-ic\" id=\"db-allfx\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 3v3M3.5 4.5h3\"></path><path d=\"M18 14v3M16.5 15.5h3\"></path><path d=\"M13 4l2 5.5 5.5 2-5.5 2L13 19l-2-5.5L5.5 11.5 11 9.5z\"></path></svg></span><span class=\"fx-db-lb\">All FX</span></button>\n      <!-- Shown only for a Lightroom \"Edit In\" handoff session (library-ui.js sets\n           window.chromasmithEditInPath and un-hides this) — writes the render straight back over\n           the file Lightroom handed us instead of the normal share-sheet save. -->\n      <button class=\"fx-db fx-db-pri\" id=\"db-save-lr\" title=\"Save back to the file Lightroom handed off — Lightroom will re-import and sync it\" data-conditional=\"\"><span class=\"fx-db-ic\" id=\"db-export-lr\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v12M8 11l4 4 4-4\"></path><path d=\"M5 21h14\"></path></svg></span>Save to Lightroom</button>\n      <button class=\"fx-db fx-db-pri\" id=\"btn-export-db\" title=\"Export at full resolution\"><span class=\"fx-db-ic\" id=\"db-export\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v12M8 11l4 4 4-4\"></path><path d=\"M5 21h14\"></path></svg></span><span class=\"fx-db-lb\">Export</span></button>\n      <!-- 2026-09-09: Tools + View + ⋯ merged into ONE settings menu, docked last (far right) —\n           matches the Library top bar's own …zoom → flags → All FX → Export → gear order. Each\n           inner div below is still built/owned by its original function (toolsBuild/viewMenuBuild/\n           ovfBuild) — only the trigger button and outer dropdown are new; see settingsBuild(). -->\n      <div id=\"fx-settings\">\n        <button class=\"fx-db fx-db-icon\" title=\"Settings — transform, edit settings, view, appearance\"><span class=\"fx-db-ic\" id=\"db-settings\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"3\"></circle><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.6 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.6a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"></path></svg></span></button>\n        <!-- 2026-09-10: two-column drill-down (the approved design) — #fx-settings-cats lists\n             the categories, #fx-settings-page holds all five content panes stacked but only the\n             ACTIVE one visible (settingsShowCat()). Each pane is still filled by its own\n             pre-existing function exactly as before (toolsBuild/viewMenuBuild/ovfBuild/\n             settingsSplitBuild/settingsHistoryBuild) — split-view and edit history still render\n             the same \"submenu, not a floating popover\" content described below, just inside a\n             selected pane instead of concatenated into one long scroll. -->\n        <div id=\"fx-settings-menu\" data-was-hidden=\"\">\n          <div id=\"fx-settings-cats\"></div>\n          <div id=\"fx-settings-page\">\n            <div id=\"fx-tools-menu\" class=\"fx-settings-pane\" data-was-hidden=\"\"></div>\n            <div id=\"fx-view-menu\" class=\"fx-settings-pane\" data-was-hidden=\"\"></div>\n            <div id=\"fx-performance-menu\" class=\"fx-settings-pane\" data-was-hidden=\"\"></div>\n            <!-- Split-view and edit history used to be a topbar icon each, opening a floating\n                 popover anchored to that specific button (#fx-split-popover/#fx-timeline-popover,\n                 still there for web/mobile mode — see the body.deskx hide rules near\n                 .fx-zoom-ctrl). On desktop they render inline here instead — no separate floating\n                 layer or viewport-clamping to get right, since this pane already scrolls. -->\n            <div id=\"fx-settings-split-list\" class=\"fx-settings-pane\" data-was-hidden=\"\"></div>\n            <div id=\"fx-settings-history-list\" class=\"fx-settings-pane\" data-was-hidden=\"\"></div>\n            <div id=\"fx-overflow-menu\" class=\"fx-settings-pane\" data-was-hidden=\"\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>","filters":"<div id=\"lib-filters-panel\" class=\"lib-fullview-only open\">\n      <div id=\"lib-filters-panel-head\">\n        <span>Filters</span>\n        <span id=\"lib-filters-panel-close\" title=\"Close\"><svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 5l14 14M19 5L5 19\"></path></svg></span>\n      </div>\n      <label id=\"lib-subfolders-wrap\" title=\"Also show photos in every subfolder, not just this one — matches Lightroom's 'Include Photos from Subfolders'\">\n        <input type=\"checkbox\" id=\"lib-subfolders\">Subfolders</label>\n      <div class=\"lib-filter-field\"><label for=\"lib-source\">Photo source</label><select id=\"lib-source\" title=\"Photo source\">\n        <option value=\"folder\">This folder</option>\n        <option value=\"edited\">All Edited</option>\n      </select></div>\n      <div class=\"lib-filter-field\"><label for=\"lib-type-filter\">File type</label><select id=\"lib-type-filter\" title=\"Filter by file type\">\n        <option value=\"all\">All types</option>\n        <option value=\"raw\">RAW</option><option value=\"jpeg\">JPEG</option>\n        <option value=\"png\">PNG</option><option value=\"tiff\">TIFF</option>\n        <!-- heic/webp/hdr/other added alongside the format-widening work: kind_of() (Rust,\n             library.rs → formats::media_kind) has always emitted \"heic\" for iPhone photos —\n             there was no option here to reach it, so HEIC files were listable but never\n             filterable. \"other\" covers the desktop-only decode_image_v1 formats\n             (TGA/DDS/QOI/FF/PNM*/JXL) plus GIF/BMP/ICO/AVIF, none of which had a bucket of\n             their own. -->\n        <option value=\"heic\">HEIC</option><option value=\"webp\">WebP</option>\n        <option value=\"hdr\">HDR/EXR</option><option value=\"other\">Other</option>\n        <option value=\"video\">Video</option>\n      </select></div>\n      <div class=\"lib-filter-field\"><label for=\"lib-camera-filter\">Camera</label><select id=\"lib-camera-filter\" title=\"Filter by camera\"><option value=\"all\">All cameras</option><option value=\"DC-S9\">DC-S9</option></select></div>\n      <div class=\"lib-filter-field\"><label for=\"lib-lens-filter\">Lens</label><select id=\"lib-lens-filter\" title=\"Filter by lens\"><option value=\"all\">All lenses</option><option value=\"LUMIX S 18-40\">LUMIX S 18-40</option></select></div>\n      <div class=\"lib-filter-field\"><label for=\"lib-iso-filter\">ISO</label><select id=\"lib-iso-filter\" title=\"Filter by ISO\"><option value=\"all\">All ISOs</option><option value=\"200\">ISO 200</option></select></div>\n      <div class=\"lib-filter-field\"><label for=\"lib-dupe-filter\">Duplicates</label><select id=\"lib-dupe-filter\" title=\"Filter by duplicate status\">\n        <option value=\"all\">All photos</option>\n        <option value=\"dupes\">Duplicates only</option>\n      </select></div>\n      <div class=\"lib-filter-field\"><label for=\"lib-synced-filter\">Google Photos sync</label><select id=\"lib-synced-filter\" title=\"Filter by Google Photos sync status\">\n        <option value=\"all\">All photos</option>\n        <option value=\"synced\">Synced to Google Photos</option>\n        <option value=\"notsynced\">Not synced</option>\n      </select></div>\n      <div class=\"lib-filter-field\"><label for=\"lib-faces-filter\">Face indexing</label><select id=\"lib-faces-filter\" title=\"Filter by face-indexing status\">\n        <option value=\"all\">All photos</option>\n        <option value=\"indexed\">Face-scanned</option>\n        <option value=\"pending\">Not face-scanned</option>\n      </select></div>\n      <!-- Own wrapper, deliberately: syncFilterUI() hides _rf.closest('label') || _rf.parentElement\n           when STARS_ENABLED is false (it is, unconditionally, in production today), so this\n           select's PARENT must be a dedicated element it alone owns — otherwise that hide call\n           takes out whatever else shares the parent. It used to share #lib-filters-pop with\n           seven other filters and #lib-filters-panel now, either of which this would have\n           hidden in full; this wrapper is what makes STARS_ENABLED=false actually mean \"hide\n           just the rating filter\" rather than \"hide whichever container it happens to sit in\". -->\n      <div id=\"lib-rating-filter-wrap\" class=\"lib-filter-field\" data-was-hidden=\"\"><label for=\"lib-rating-filter\">Star rating</label>\n        <select id=\"lib-rating-filter\" title=\"Filter by star rating\">\n          <option value=\"all\">Any rating</option>\n          <option value=\"0\">Unrated</option>\n          <option value=\"1\">★1+</option>\n          <option value=\"2\">★2+</option>\n          <option value=\"3\">★3+</option>\n          <option value=\"4\">★4+</option>\n          <option value=\"5\">★5</option>\n        </select>\n      </div>\n      <div class=\"lib-filter-field\"><label for=\"lib-tag-filter\">Tags</label><select id=\"lib-tag-filter\" title=\"Filter by tag\">\n        <option value=\"all\">All tags</option>\n        <option value=\"red\">Rejected (X)</option>\n        <option value=\"green\">Picked (flag)</option>\n        <option value=\"edited\">Edited</option>\n        <option value=\"noedited\">Not edited</option>\n        <option value=\"favorite\">Favorites</option>\n        <option value=\"none\">Unflagged</option>\n      </select></div>\n      <button class=\"lib-btn\" id=\"lib-filters-clear\">Clear all</button>\n      <div class=\"lib-fp-label\">Display</div>\n      <select id=\"lib-views\" title=\"Saved filter + sort views\"><option value=\"\">Views…</option><option value=\"__save\">+ Save current…</option></select>\n      <!-- lib-thumbsize (zoom), lib-showtitle/lib-hideicons/lib-zerogap and lib-metadisp all\n           relocated to the top bar / gear View menu above — kept as the single live copy of\n           each id there, not duplicated here. -->\n    </div>"};
